<template><ChoiceOverlay :title="title" :choices="choices" :countdown="timeout" :developer-mode="dev" @select="select"/></template><script setup lang="ts">import ChoiceOverlay from './choice/ChoiceOverlay.vue';import type {ChoiceItem} from '../data/story';const props=defineProps<{title?:string;choices:ChoiceItem[];timeout?:number;dev?:boolean}>();const emit=defineEmits<{pick:[ChoiceItem]}>();function select(id:string){const c=props.choices.find(c=>c.id===id);if(c)emit('pick',c)}</script>